                    allowed_hours?: {
                        /** @description An IANA time zone, such as America/Chicago. */
                        tz: string;
                        /** @description HH:MM */
                        start: string;
                        /** @description HH:MM; earlier than start runs past midnight. */
                        end: string;
                        days: ("mon" | "tue" | "wed" | "thu" | "fri" | "sat" | "sun")[];
                    } | null;
                    allowed_actions?: ("post" | "quote" | "accept" | "pay" | "withdraw" | "message" | "lead_post" | "lead_buy" | "capacity_quote")[] | null;
                    /** @description A seller’s quote at or under the request’s ceiling, inside every other rule, is accepted for the owner automatically. */
                    auto_accept_under_ceiling?: boolean;
                    /**
                     * @description The owner’s email when a rule stops the agent: each time, once a day, or never.
                     * @enum {string}
                     */
                    notify?: "each" | "daily" | "none";
                    /** @enum {string} */
                    notify_channel?: "email" | "telegram";
                    /** @description true to save a change that loosens a rule. */
                    confirm?: boolean;
